mapper.select:
SELECT p.product_id, p.product_name, p.description, p.price, p.category_id, c.category_name, p.seller_id, u.nickname AS seller_nickname, p.stock, p.status, p.view_count, p.is_bargainable, p.discount_rate, p.audit_status, p.audit_result, p.created_at, p.updated_at FROM products p LEFT JOIN users u ON p.seller_id = u.user_id LEFT JOIN categories c ON p.category_id = c.category_id
AND p.product_name LIKE CONCAT('%', #{productName}, '%')
AND p.status = #{status}
AND p.category_id = #{categoryId}
AND p.audit_status = #{auditStatus}
ORDER BY p.created_at DESC
